	// EXPECT-1: load_spikes_e2e_ms < 3100
	// RESULT-1: REFUTED (actual=3243.322405)
	// HYPOTHESIS-2: Increasing cache hit rate bonus to 0.4 for sessions and using a graduated KV penalty starting at 0.7 will reduce cache_warmup_e2e_ms below 4500
	// MECHANISM-2: Stronger cache affinity keeps session/prefix requests on warm instances. Earlier KV pressure avoidance (0.7 vs 0.85) prevents routing to instances about to evict cached blocks
	// EXPECT-2: cache_warmup_e2e_ms < 4500
	// RESULT-2: CONFIRMED (actual=4205.5246654)
	// HYPOTHESIS-3: The combined improvements will push combined_score above -4100
	// MECHANISM-3: Nonlinear load penalty helps spikes, stronger cache affinity helps warmup, and earlier KV avoidance helps both
	// EXPECT-3: combined_score > -4100

	// Compute composite scores from all scorers
	scores := make(map[string]float64, len(snapshots))
